#!/usr/bin/env python3
"""Apply a password-change record generated by the site. Usage: python3 tools/set_hash.py '{"u":"daniel","name":"Daniel","h":"..."}'"""
import json, sys, pathlib
rec = json.loads(sys.argv[1]); p = pathlib.Path(__file__).resolve().parent.parent / "docs" / "auth.json"
d = json.loads(p.read_text(encoding="utf-8")); u = rec["u"].strip().lower()
d["users"] = [x for x in d["users"] if x["u"] != u] + [{"u": u, "name": rec.get("name", u), "h": rec["h"]}]
p.write_text(json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8"); print("ok:", u)
